    sources: { fr: ["Déclaration ministérielle de Kampala sur la migration, l'environnement et le changement climatique (2022)","Union africaine — Convention de Kampala (2009), article 5(4) sur le déplacement lié aux catastrophes"], en: ["Kampala Ministerial Declaration on Migration, Environment and Climate Change (2022)","African Union — Kampala Convention (2009), Article 5(4) on disaster-related displacement"] },
